export type AgentStreamEvent =
  | { type: "text"; delta: string }
  | { type: "reasoning"; delta: string }
  | { type: "source"; title: string; url?: string; id?: string }
  | { type: "tool-start"; id: string; name: string }
  | { type: "tool-end"; id: string; error?: boolean }
  | { type: "error"; message: string }
  | { type: "done" };

export type AgentStreamPart =
  | { type: "text"; text: string }
  | { type: "reasoning"; text: string }
  | { type: "source-url"; sourceId?: string; url?: string; title: string }
  | { type: "dynamic-tool"; toolCallId: string; toolName: string; state: "input-available" | "output-available" | "output-error" };

export type AgentStreamState = {
  /** The same values as the AI SDK's useChat, so useAgentStatus reads it directly. */
  status: "ready" | "submitted" | "streaming" | "error";
  /** The assistant turn being streamed, as one message of parts. */
  messages: Array<{ role: "assistant"; parts: AgentStreamPart[] }>;
  error?: Error;
};

export type AgentStreamAction = AgentStreamEvent | { type: "request" } | { type: "stopped" };

export type SSEMessage = { event?: string; data: string; id?: string };

export type SSEMapper = (message: SSEMessage) => AgentStreamEvent | AgentStreamEvent[] | null | undefined;

export type UseAgentStreamOptions = {
  /** Endpoint that responds with server-sent events. send(body) POSTs JSON to it. */
  api?: string;
  /** Replaces the default request, for custom headers, methods, or bodies. */
  fetch?: (body: unknown, signal: AbortSignal) => Promise<Response>;
  /** Maps each server-sent event to AgentStreamEvents. Defaults to Crate's JSON events. */
  map?: SSEMapper;
};

export type AgentStream = AgentStreamState & {
  /** All text streamed so far in the current turn. */
  text: string;
  /** Starts a new turn. */
  send: (body?: unknown) => Promise<void>;
  /** Cancels the current turn. */
  stop: () => void;
};

import { Agent, run } from "@openai/agents";
import { agentEventsResponse } from "@/lib/agent-stream";
import { fromOpenAIAgents } from "@/lib/agent-stream-openai-agents";

const agent = new Agent({ name: "Assistant", instructions: "Help the user." });

export async function POST(request: Request) {
  const { message } = await request.json();
  return agentEventsResponse(fromOpenAIAgents(await run(agent, message, { stream: true })));
}

import { agentEventsResponse } from "@/lib/agent-stream";
import { fromLangChain } from "@/lib/agent-stream-langchain";
import { graph } from "./graph";

export async function POST(request: Request) {
  const { message } = await request.json();
  const events = graph.streamEvents({ messages: [{ role: "user", content: message }] }, { version: "v2" });
  return agentEventsResponse(fromLangChain(events));
}

"use client";

import { AgentState } from "@/components/agent-wait-states/agent-state";
import { useAgentStatus } from "@/hooks/use-agent-status";
import { useAgentStream } from "@/hooks/use-agent-stream";

export function Assistant() {
  const stream = useAgentStream({ api: "/api/agent" });
  const status = useAgentStatus(stream);
  const ask = () => stream.send({ message: "Plan my week" });

  return (
    <>
      <button type="button" onClick={ask}>Ask</button>
      <AgentState status={status} text={stream.text} errorMessage={stream.error?.message} onRetry={ask} />
    </>
  );
}

const stream = useAgentStream({
  api: "/api/chat",
  map: (message) => {
    if (message.data === "[DONE]") return { type: "done" };
    const delta = JSON.parse(message.data).choices[0]?.delta?.content;
    return delta ? { type: "text", delta } : null;
  },
});

